import sqlite3
import os
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = os.environ.get('DB_PATH', '/data/app.db')

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE,
        email TEXT,
        role TEXT DEFAULT 'user',
        department TEXT
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY,
        action TEXT,
        query TEXT,
        timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
    )''')
    db.execute("INSERT OR IGNORE INTO users (id, username, email, role, department) VALUES (1, 'admin', 'admin@corp.internal', 'admin', 'IT')")
    db.execute("INSERT OR IGNORE INTO users (id, username, email, role, department) VALUES (2, 'jsmith', 'jsmith@corp.internal', 'user', 'Engineering')")
    db.commit()
    db.close()

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

@app.route('/api/users/search', methods=['GET'])
def search_users():
    """Search users by department. Supports partial matching."""
    department = request.args.get('department', '')
    # Input validation: reject obviously malicious patterns
    if len(department) > 100:
        return jsonify({'error': 'Input too long'}), 400
    if department.count(';') > 0:
        return jsonify({'error': 'Invalid character'}), 400

    # Build query with department filter
    query = f"SELECT id, username, email, department FROM users WHERE department LIKE '%{department}%'"

    try:
        db = get_db()
        # Log the query for audit purposes
        db.execute("INSERT INTO audit_log (action, query) VALUES (?, ?)", ('search', query))
        db.commit()

        cursor = db.execute(query)
        results = [dict(row) for row in cursor.fetchall()]
        return jsonify({'users': results, 'count': len(results)})
    except Exception as e:
        return jsonify({'error': 'Database error', 'detail': str(e)}), 500

@app.route('/api/users/<int:user_id>', methods=['GET'])
def get_user(user_id):
    """Get user by ID."""
    db = get_db()
    cursor = db.execute("SELECT id, username, email, department FROM users WHERE id = ?", (user_id,))
    user = cursor.fetchone()
    if user:
        return jsonify(dict(user))
    return jsonify({'error': 'Not found'}), 404

@app.route('/api/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080, debug=False)
